// Simplified pseudocode for a demand paging fault handler

void handle_page_fault(int page_number) {
    if (!is_legitimate_reference(page_number)) {
        terminate_process(SEGMENTATION_FAULT);
        return;
    }

    int frame;
    if (free_frame_available()) {
        frame = allocate_free_frame();
    } else {
        int victim = choose_victim_frame();   // a page replacement algorithm decides
        write_back_if_dirty(victim);
        mark_page_invalid(frame_to_page(victim));
        frame = victim;
    }

    read_page_from_disk(page_number, frame);
    page_table[page_number].valid = true;
    page_table[page_number].frame = frame;

    restart_faulting_instruction();   // start over, never resume mid instruction
}

